package com.portfolio.shopsphere.controller;import com.portfolio.shopsphere.model.Order;import com.portfolio.shopsphere.repo.OrderRepository;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orders") @CrossOrigin(origins="http://localhost:5173")public class OrderController{final OrderRepository r;OrderController(OrderRepository r){this.r=r;}@GetMapping List<Order>all(@RequestParam(required=false)String email){return email==null?r.findAll():r.findByCustomerEmailIgnoreCase(email);}@PostMapping ResponseEntity<Order>create(@RequestBody Order o){o.status="PLACED";return ResponseEntity.status(HttpStatus.CREATED).body(r.save(o));}@PatchMapping("/{id}/status")ResponseEntity<Order>status(@PathVariable Long id,@RequestParam String value){return r.findById(id).map(o->{o.status=value.toUpperCase();return ResponseEntity.ok(r.save(o));}).orElse(ResponseEntity.notFound().build());}}
